"""Rebuild published pages after editing data/site.json. Python 3, no dependencies."""
from pathlib import Path
import json,html,os
from urllib.parse import quote,urlencode
ROOT=Path(__file__).resolve().parents[1]
D=json.loads((ROOT/'data/site.json').read_text())
C=D['clinic']; esc=html.escape
TOOLS=[
 ('nerve-explorer','upper-limb-en.html','Explorateur des nerfs du membre supérieur','Upper-limb nerve explorer','Plexus brachial, myotomes et localisation des lésions.','Brachial plexus, myotomes and lesion localization.','EN','EMG'),
 ('explorateur-nerfs-membres-supérieurs','upper-limb-fr.html','Explorateur des nerfs du membre supérieur','Upper-limb nerve explorer','La version française, du plexus brachial à la main.','The French version, from brachial plexus to hand.','FR','EMG'),
 ('lower-extremity-nerve-explorer','lower-limb.html','Explorateur des nerfs du membre inférieur','Lower-limb nerve explorer','Plexus lombo-sacré, territoires et localisation.','Lumbosacral plexus, territories and localization.','FR / EN','EMG'),
 ('fascicle-explorer','fascicle.html','Explorateur des fascicules intraneuraux','Intraneural fascicle explorer','Explorer l’organisation des fascicules à l’intérieur des nerfs.','Explore the organization of fascicles within nerves.','FR / EN','EMG'),
 ('motor-block-explorer','motor-blocks.html','Explorateur des blocs moteurs','Motor block explorer','Membres supérieurs et inférieurs réunis dans un seul outil.','Upper and lower limbs together in one tool.','FR / EN','Neuro'),
 ('muscle-ultrasound','muscle-ultrasound.html','Muscles en échographie','Muscle ultrasound','Anatomie musculaire et vidéos échographiques.','Muscle anatomy and ultrasound videos.','FR / EN','Neuro')]
URLS=[]
from faq_content import faq_html, faq_teaser
def rel(path,target):return os.path.relpath(target or '.',start=os.path.dirname(path) or '.').replace(os.sep,'/')
def page(path,lang,title,desc,body,active='home',alternate=None,cls=''):
 fr=lang=='fr';r=lambda t:rel(path,t)
 home='index.html' if fr else 'en/index.html';edu='education/index.html' if fr else 'en/education/index.html'
 canonical=D['domain']+'/'+quote(path.replace('index.html',''),safe='/')
 alt=''
 if alternate:
  alturl=D['domain']+'/'+quote(alternate.replace('index.html',''),safe='/')
  alt=f'<link rel="alternate" hreflang="{lang}" href="{canonical}"><link rel="alternate" hreflang="{"en" if fr else "fr"}" href="{alturl}">'
 name=D['name'];t=lambda f,e:f if fr else e
 nav=f'''<a class="skip" href="#main">{t('Aller au contenu','Skip to content')}</a><header class="header"><div class="wrap navrow"><a class="brand" href="{r(home)}"><span class="monogram" aria-hidden="true">AB</span><span>{esc(name)}<small>{t('Médecine physique & réadaptation','Physical medicine & rehabilitation')}</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" class="navlinks" aria-label="{t('Navigation principale','Main navigation')}"><a href="{r(home)}" {'aria-current="page"' if active=='home' else ''}>{t('Patients','Patients')}</a><a href="{r(home)}#services">{t('Expertises','Expertise')}</a><a href="{r(edu)}" {'aria-current="page"' if active=='edu' else ''}>{t('Éducation médicale','Medical education')}</a><a href="{r('faq/index.html' if fr else 'en/faq/index.html')}">FAQ</a><a href="tel:{C['phoneLink']}">{esc(C['phone'])}</a><a class="lang" href="{r(alternate or ('en/index.html' if fr else 'index.html'))}" lang="{t('en','fr')}" aria-label="{t('English version','Version française')}">{t('EN','FR')}</a></nav></div></header>'''
 footer=f'''<footer class="footer"><div class="wrap"><div>© {esc(name)} · {t('Physiatre','Physiatrist')}<br>Montréal</div><div class="footer-links"><a href="{D['youtube']}">YouTube</a><a href="{D['instagram']}">Instagram</a><a href="{r(home)}#consultations">Contact</a></div></div></footer>'''
 structured={"@context":"https://schema.org","@type":"Person","name":"Andrei Bursuc","honorificPrefix":"Dr","jobTitle":t('Physiatre','Physiatrist'),"url":D['domain'],"image":D['domain']+'/assets/portrait.jpg',"sameAs":[D['youtube'],D['instagram']]}
 out=f'''<!doctype html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(desc,quote=True)}"><meta name="theme-color" content="#112d45"><link rel="canonical" href="{canonical}">{alt}<link rel="icon" type="image/png" sizes="96x96" href="{r('assets/favicon.png')}"><link rel="apple-touch-icon" href="{r('assets/apple-touch-icon.png')}"><link rel="stylesheet" href="{r('assets/style.css')}"><script defer src="{r('assets/site.js')}"></script><script type="application/ld+json">{json.dumps(structured,ensure_ascii=False)}</script></head><body class="{cls}">{nav}{body}{footer}</body></html>'''
 p=ROOT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(out)
 if path!='404.html':URLS.append(canonical)

def home(lang):
 fr=lang=='fr';t=lambda f,e:f if fr else e
 path='index.html' if fr else 'en/index.html';r=lambda x:rel(path,x);edu=r('education/index.html' if fr else 'en/education/index.html')
 services=[('emg','Électromyographie','Electromyography','Évaluer le fonctionnement des nerfs et des muscles pour aider à préciser le diagnostic.','Assess nerve and muscle function to help clarify the diagnosis.'),('spasticite','Spasticité','Spasticity','Prise en charge de la raideur et des spasmes musculaires associés aux atteintes neurologiques.','Management of muscle stiffness and spasms associated with neurological conditions.'),('infiltrations','Infiltrations échoguidées','Ultrasound-guided injections','Utiliser l’échographie pour cibler une articulation, un tendon ou un nerf.','Use ultrasound to target a joint, tendon or nerve.'),('migraine','Migraine chronique','Chronic migraine','Injections de toxine botulinique dans le cadre de la prise en charge des migraines chroniques.','Botulinum toxin injections as part of chronic migraine management.')]
 cards=''.join(f'<article class="service"><img src="{r("assets/"+s[0]+".jpg")}" alt="{esc(t(s[1],s[2]))}" width="600" height="600" loading="lazy"><span class="num">0{i+1}</span><h3>{t(s[1],s[2])}</h3><p>{t(s[3],s[4])}</p></article>' for i,s in enumerate(services))
 mapurl='https://www.google.com/maps/search/?'+urlencode({'api':'1','query':C['street']+' '+C['city']})
 body=f'''<main id="main"><div class="wrap hero"><div><p class="eyebrow">{t('Dr Andrei Bursuc · Physiatre','Dr Andrei Bursuc · Physiatrist')}</p><h1>{t('Médecine physique<br>& réadaptation.','Physical medicine<br>& rehabilitation.')}</h1><p class="intro">{t('Une pratique axée sur la médecine neuro-musculosquelettique, la mobilité et l’autonomie.','A practice focused on neuromusculoskeletal medicine, mobility and independence.')}</p><div class="hero-contact" id="consultations"><h2>{esc(C['name'])}</h2><p>{esc(C['street'])}<br>{esc(C['city'])}</p><div class="hero-contact-links"><a href="tel:{C['phoneLink']}">{esc(C['phone'])}</a><a href="mailto:{C['email']}">{esc(C['email'])}</a></div><p class="contact-meta">Fax : {esc(C['fax'])} · <a href="{esc(mapurl,quote=True)}">{t('Itinéraire','Directions')}</a></p><p class="contact-meta">{t('Une référence médicale est requise.','A physician referral is required.')}</p></div><div class="actions"><a class="button" href="tel:{C['phoneLink']}">{t('Appeler la clinique','Call the clinic')}</a><a class="button secondary" href="{edu}">{t('Outils d’apprentissage','Learning tools')}</a></div></div><div class="portrait-frame"><img src="{r('assets/portrait.jpg')}" alt="{t('Portrait du Dr Andrei Bursuc','Portrait of Dr Andrei Bursuc')}" width="650" height="715" fetchpriority="high"><div class="portrait-caption"><strong>Andrei Bursuc</strong>{D['credentials']} · {t('Physiatre','Physiatrist')}</div></div></div><div class="ribbon"><div class="wrap"><span>{t('Électromyographie','Electromyography')}</span><span>{t('Neuro-orthopédie','Neuro-orthopaedics')}</span><span>{t('Spasticité','Spasticity')}</span><span>{t('Échographie musculosquelettique','Musculoskeletal ultrasound')}</span></div></div><section class="section wrap" id="services"><div class="section-head"><div><p class="eyebrow">{t('Domaines de pratique','Areas of practice')}</p><h2>{t('Une approche neuro-MSK.','A neuro-MSK approach.')}</h2></div><p>{t('Évaluation et traitements en médecine physique et réadaptation.','Assessment and treatment in physical medicine and rehabilitation.')}</p></div><div class="services">{cards}</div><p class="note">{t('Une référence médicale est requise. Communiquez avec la clinique pour connaître les modalités de consultation.','A physician referral is required. Contact the clinic for appointment requirements.')}</p></section><section class="section soft" id="parcours"><div class="wrap about"><div><p class="eyebrow">{t('Parcours','Background')}</p><h2>{t('Dr Andrei Bursuc','Dr Andrei Bursuc')}</h2></div><div class="about-text"><p>{t('Spécialiste en médecine physique et réadaptation, le Dr Bursuc exerce à Montréal à la Clinique de physiatrie CDN. Sa pratique comprend l’électromyographie, la gestion de la spasticité et les infiltrations échoguidées.','A specialist in physical medicine and rehabilitation, Dr Bursuc practises in Montréal at Clinique de physiatrie CDN. His practice includes electromyography, spasticity management and ultrasound-guided injections.')}</p><ul class="training"><li><strong>{t('Doctorat en médecine','Doctor of Medicine')}</strong><span>Université de Montréal</span></li><li><strong>{t('Spécialité en médecine physique et réadaptation','Specialty in Physical Medicine and Rehabilitation')}</strong><span>Université de Montréal</span></li><li><strong>{t('Maîtrise en médecine expérimentale','Master of Science in Experimental Medicine')}</strong><span>McGill University</span></li></ul></div></div></section><section class="section wrap"><div class="education-callout"><div><p class="eyebrow">{t('Pour les professionnels et les étudiants','For clinicians and students')}</p><h2>{t('Explorer. Comprendre.<br>Apprendre.','Explore. Understand.<br>Learn.')}</h2><p>{t('Des outils interactifs pour approfondir l’anatomie, la localisation neurologique et les techniques en neuro-orthopédie.','Interactive tools to explore anatomy, neurological localization and neuro-orthopaedic techniques.')}</p><a class="button actions" href="{edu}">{t('Accéder aux outils d’éducation','Open the education tools')} <span aria-hidden="true">↗</span></a></div><ul class="edu-list"><li>{t('Explorateurs des nerfs · membres supérieurs et inférieurs','Nerve explorers · upper and lower limbs')}</li><li>{t('Territoires des blocs moteurs','Motor block territories')}</li><li>{t('Muscles et vidéos en échographie','Muscle ultrasound and videos')}</li></ul></div></section></main>'''
 body=body.replace('</main>',faq_teaser(lang, r('faq/index.html' if fr else 'en/faq/index.html'))+'</main>')
 page(path,lang,t('Dr Andrei Bursuc — Physiatre à Montréal','Dr Andrei Bursuc — Montréal Physiatrist'),t('Physiatre à Montréal : EMG, spasticité, infiltrations échoguidées et migraine chronique. Coordonnées et outils d’éducation médicale.','Montréal physiatrist: EMG, spasticity, ultrasound-guided injections and chronic migraine. Contact information and medical education tools.'),body,alternate='en/index.html' if fr else 'index.html')

def education(lang):
 fr=lang=='fr';t=lambda f,e:f if fr else e
 path='education/index.html' if fr else 'en/education/index.html';r=lambda x:rel(path,x)
 sections=''
 for group in ['EMG','Neuro']:
  cards=''
  for slug,file,tf,te,df,de,badge,category in TOOLS:
   if category!=group:continue
   target=('education/' if fr else 'en/education/')+slug+'/index.html'
   cards+=f'<a class="tool-card" href="{r(target)}"><span class="badge">{badge}</span><h3>{t(tf,te)}</h3><p>{t(df,de)}</p><span class="open">{t("Ouvrir l’outil","Open tool")} <span aria-hidden="true">↗</span></span></a>'
  sections+=f'<section class="section compact wrap"><div class="section-head"><div><p class="eyebrow">{t("Outils interactifs","Interactive tools")}</p><h2>{"EMG" if group=="EMG" else t("Neuro-orthopédie","Neuro-orthopaedics")}</h2></div></div><div class="tool-grid">{cards}</div></section>'
 body=f'''<main id="main"><section class="edu-hero"><div class="wrap"><p class="eyebrow">{t('Professionnels de santé · Étudiants','Healthcare professionals · Students')}</p><h1>{t('Éducation médicale.','Medical education.')}</h1><p>{t('Explorer les nerfs, les territoires moteurs et l’anatomie échographique avec les outils du Dr Andrei Bursuc.','Explore nerves, motor territories and ultrasound anatomy with Dr Andrei Bursuc’s tools.')}</p></div></section>{sections}<section class="section soft"><div class="wrap video-row"><div><p class="eyebrow">{t('Vidéothèque','Video library')}</p><h2>{t('L’anatomie en images.','Anatomy in view.')}</h2><p>{t('Vidéos éducatives en anatomie échographique, localisation clinique et techniques interventionnelles. Pour toute réutilisation pédagogique, citez la chaîne et le lien de la vidéo originale.','Educational videos on ultrasound anatomy, clinical localization and interventional techniques. When reusing videos for teaching, credit the channel and link to the original video.')}</p></div><a class="button" href="{D['youtube']}">{t('Voir les vidéos sur YouTube','Watch on YouTube')} ↗</a></div></section></main>'''
 page(path,lang,t('Éducation médicale et outils interactifs — Dr Andrei Bursuc','Medical education and interactive tools — Dr Andrei Bursuc'),t('Explorateurs des nerfs, blocs moteurs et muscles en échographie : outils interactifs en EMG et neuro-orthopédie.','Nerve explorers, motor blocks and ultrasound muscles: interactive tools for EMG and neuro-orthopaedics.'),body,active='edu',alternate='en/education/index.html' if fr else 'education/index.html')
 for slug,file,tf,te,df,de,badge,category in TOOLS:
  toolpath=('education/' if fr else 'en/education/')+slug+'/index.html';tr=lambda x:rel(toolpath,x)
  body=f'''<main id="main"><div class="wrap tool-top"><div><a class="back" href="{tr(path)}">← {t('Tous les outils','All tools')}</a><h1>{t(tf,te)}</h1></div><a class="button secondary" href="{tr('tools/'+file)}">{t('Ouvrir en pleine page','Open full page')} ↗</a></div><iframe class="tool-frame" src="{tr('tools/'+file)}" title="{esc(t(tf,te))}" allow="fullscreen" allowfullscreen></iframe></main>'''
  other=('en/education/' if fr else 'education/')+slug+'/index.html'
  page(toolpath,lang,t(tf,te)+' — Dr Andrei Bursuc',t(df,de),body,active='edu',alternate=other,cls='tool-page')
for lang in ['fr','en']:
 home(lang);education(lang)
 fp='faq/index.html' if lang=='fr' else 'en/faq/index.html'
 page(fp,lang,'Questions fréquentes — Physiatre à Montréal | Dr Andrei Bursuc' if lang=='fr' else 'Frequently asked questions — Montréal physiatrist | Dr Andrei Bursuc','Consultation en physiatrie à Montréal, EMG, préparation et rendez-vous : réponses aux questions des patients.' if lang=='fr' else 'Physiatry in Montréal, EMG, preparation and appointments: answers to common patient questions.',faq_html(lang,C,rel(fp,'index.html' if lang=='fr' else 'en/index.html')),active='faq',alternate='en/faq/index.html' if lang=='fr' else 'faq/index.html')
# Preserve previously shared links while retiring the separate block applications.
for prefix in ['education/','en/education/']:
 for old in ['upper-extremity-nerve-blocks-blocs-moteurs-membre-supérieur','nerve-blocks-lower-extremity']:
  dest=ROOT/prefix/old/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
  target='../motor-block-explorer/index.html'
  dest.write_text('<!doctype html><html lang="'+('en' if prefix.startswith('en/') else 'fr')+'"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url='+target+'"><link rel="canonical" href="'+D['domain']+'/'+prefix+'motor-block-explorer/"><title>Motor block explorer</title><a href="'+target+'">Blocs moteurs — Motor blocks</a></html>')
for old in ['upper-blocks.html','lower-blocks.html']:
 (ROOT/'tools'/old).write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=motor-blocks.html"><title>Motor block explorer</title><a href="motor-blocks.html">Blocs moteurs — Motor blocks</a></html>')
# Keep the former Google Sites /home entry point working.
p=ROOT/'home/index.html';p.parent.mkdir(exist_ok=True);p.write_text('<!doctype html><html lang="fr"><meta charset="utf-8"><meta http-equiv="refresh" content="0;url=../"><link rel="canonical" href="'+D['domain']+'/"><title>Dr Andrei Bursuc</title><a href="../">Accéder au site / Open website</a></html>')
page('404.html','fr','Page introuvable — Dr Andrei Bursuc','Retrouvez le site du Dr Andrei Bursuc.','<main id="main" class="wrap missing"><p class="eyebrow">404</p><h1>Cette page est introuvable.</h1><p>Retrouvez les consultations et les outils d’éducation depuis l’accueil.</p><a class="button" href="/">Retour à l’accueil</a></main>')
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+esc(u)+'</loc></url>' for u in URLS)+'</urlset>')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+D['domain']+'/sitemap.xml\n')
(ROOT/'.nojekyll').touch()
print('Generated',len(URLS),'pages + /home and 404; contact information from data/site.json')
